package com.chondrimaishrat.elearning.web;
import com.chondrimaishrat.elearning.auth.SessionAccess; import com.chondrimaishrat.elearning.quiz.*; import com.chondrimaishrat.elearning.user.*; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import java.util.Map;
@Controller public class QuizController {private final QuizService quizzes;private final SessionAccess access;public QuizController(QuizService q,SessionAccess a){quizzes=q;access=a;}@GetMapping("/instructor/courses/{id}/quiz")public String manage(@PathVariable Long id,HttpSession s,Model m){try{access.requireRole(s,UserRole.INSTRUCTOR);m.addAttribute("courseId",id);m.addAttribute("questionForm",new QuestionForm());m.addAttribute("questions",quizzes.questions(id));return "quiz-manage";}catch(IllegalArgumentException e){return "redirect:/login";}}@PostMapping("/instructor/courses/{id}/quiz")public String add(@PathVariable Long id,@Valid QuestionForm f,BindingResult b,HttpSession s,Model m){try{UserAccount u=access.requireRole(s,UserRole.INSTRUCTOR);if(b.hasErrors()){m.addAttribute("courseId",id);m.addAttribute("questions",quizzes.questions(id));return "quiz-manage";}quizzes.add(u,id,f);return "redirect:/instructor/courses/"+id+"/quiz";}catch(IllegalArgumentException e){return "redirect:/login";}}@GetMapping("/courses/{id}/quiz")public String take(@PathVariable Long id,HttpSession s,Model m){try{access.requireRole(s,UserRole.STUDENT);m.addAttribute("courseId",id);m.addAttribute("questions",quizzes.questions(id));return "quiz-take";}catch(IllegalArgumentException e){return "redirect:/login";}}@PostMapping("/courses/{id}/quiz")public String submit(@PathVariable Long id,@RequestParam Map<String,String> answers,HttpSession s,Model m){try{QuizAttempt a=quizzes.submit(access.requireRole(s,UserRole.STUDENT),id,answers);m.addAttribute("attempt",a);return "quiz-result";}catch(IllegalArgumentException e){return "redirect:/courses";}}}
